<?php
declare(strict_types=1);use Acorn\SafetyHealthcheck\Content\{ContentPublisher,ContentVersionRepository};use Acorn\SafetyHealthcheck\Database\Schema;
final class ContentVersioningTest extends IntegrationTestCase{public function test_draft_clones_questions_and_all_recommendations():void{global$wpdb;$live=(new ContentVersionRepository)->getPublished();$questions=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Schema::table('questions').' WHERE content_version_id=%d',$live['id']));$recommendations=(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Schema::table('recommendations').' WHERE content_version_id=%d',$live['id']));$draft=(new ContentPublisher)->createDraftFromPublished(1);self::assertSame($questions,(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Schema::table('questions').' WHERE content_version_id=%d',$draft)));self::assertSame($recommendations,(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Schema::table('recommendations').' WHERE content_version_id=%d',$draft)));$this->expectException(RuntimeException::class);(new ContentPublisher)->publish($draft,1);}}
